    표2_역사적배경: [
        {"항목":"연좌제 거부", "내용":"고대 근동에서는 반역자의 가족 전체를 처형하는 것이 일반적이었다. 아마샤가 자녀를 살려준 것은 모세 율법(신 24:16)에 따른 것으로, 당시로서는 매우 진보적인 조치였다", "목회적활용":"성경의 정의는 개인의 책임에 기초하며, 이는 무고한 자를 보호하는 원리입니다"},
        {"항목":"모세 율법의 인용", "내용":"아마샤가 신명기 24:16을 직접 인용하며 율법에 따라 행동한 것은 그가 율법을 알고 따르려 했음을 보여준다. 이는 그의 초기 경건한 모습의 한 단면이다", "목회적활용":"하나님의 말씀을 알고 그에 따라 행동하는 것이 바른 결정의 기초입니다"},
        {"항목":"역대기의 율법 강조", "내용":"역대기 기자가 이 율법 인용을 특별히 기록한 것은 율법 준수의 중요성을 강조하기 위함이다. 왕도 율법 위에 있지 않음을 보여준다", "목회적활용":"지도자도 하나님의 말씀 아래에 있으며, 말씀에 따라 통치해야 합니다"}
    ],
    표3_신학적의미: [
        {"교리":"개인 책임의 원리", "설명":"각 사람이 자기 죄로 죽는다는 원리는 연좌제를 부정하고 개인의 도덕적 책임을 확립하는 성경적 정의의 핵심이다", "관련구절":"신명기 24:16, 에스겔 18:20"},
        {"교리":"율법에 의한 통치", "설명":"왕이 율법을 인용하며 그에 따라 행동한 것은 이스라엘에서 왕도 율법 아래에 있다는 원리를 보여준다", "관련구절":"신명기 17:18-20, 여호수아 1:8"},
        {"교리":"정의와 자비의 균형", "설명":"죄인은 처벌하되 무고한 자녀는 보호하는 것은 하나님의 정의와 자비가 함께 작용하는 모습을 보여준다", "관련구절":"미가 6:8, 시편 85:10"}
    ],
    표4_예표론: [
        {"구분":"개인 책임의 원리와 그리스도의 대속적 죽음", "내용":"각 사람이 자기 죄로 죽는다는 원리가 선포되었다", "그리스도연결":"그리스도는 우리의 죄를 대신 지심으로 개인 책임의 원리를 넘어서는 은혜를 보여주셨다(이사야 53:5-6)"},
        {"구분":"율법에 따른 통치와 그리스도의 율법 완성", "내용":"아마샤가 모세 율법에 따라 통치했다", "그리스도연결":"그리스도는 율법을 폐하러 오신 것이 아니라 완성하러 오셨다(마태복음 5:17)"},
        {"구분":"무고한 자녀의 보호와 그리스도의 어린이 사랑", "내용":"반역자의 무고한 자녀들이 보호받았다", "그리스도연결":"예수님은 어린아이들을 품으시며 하나님 나라가 이런 자의 것이라 하셨다(마가복음 10:14)"}
    ],
    표5_매튜헨리: [
        {"영어원문":"He put their children not to death, according to the law of Moses, that the children should not die for the fathers.", "한국어번역":"그가 모세의 율법대로 그 자녀들은 죽이지 않았으니, 자녀가 아버지 때문에 죽어서는 안 된다는 것이다.", "핵심통찰":"율법에 따른 통치는 정의와 자비를 동시에 실현합니다"},
        {"영어원문":"It is a great instance of his piety that he would be ruled by the word of God.", "한국어번역":"하나님의 말씀에 의해 다스려지고자 한 것은 그의 경건함의 좋은 사례이다.", "핵심통찰":"말씀에 따라 결정하는 것이 지도자의 참된 경건입니다"},
        {"영어원문":"Every man shall die for his own sin, is a rule of equity.", "한국어번역":"각 사람이 자기 죄로 죽을 것이라는 것은 형평의 규칙이다.", "핵심통찰":"개인 책임의 원리는 하나님의 공의의 근본입니다"}
    ],
    표6_설교자료: [
        {"대지":"제목", "내용":"말씀에 따른 정의", "예화_적용":"모세 율법에 따라 반역자의 자녀를 살려둔 아마샤의 결정을 통해 성경적 정의를 배웁니다"},
        {"대지":"서론", "내용":"아버지를 죽인 자들을 처형하면서도 그 자녀들은 살려두었습니다. 그 이유는 무엇일까요? '모세의 율법에 기록된 대로' 행한 것입니다", "예화_적용":"감정이 아닌 말씀에 따른 결정이 참된 정의를 실현합니다"},
        {"대지":"1대지: 개인 책임의 원리", "내용":"'각 사람은 자기의 죄로 말미암아 죽임을 당할 것이라.' 부모의 죄가 자녀에게 전가되지 않는 것은 하나님의 공의의 핵심 원리입니다", "예화_적용":"범죄자의 가족이 사회적 낙인을 받는 현실에서, 성경은 개인의 죄를 가족에게 전가하지 말라고 가르칩니다"},
        {"대지":"2대지: 율법의 권위", "내용":"왕이 율법을 인용하며 그에 따라 행동했습니다. 왕이라도 하나님의 말씀 위에 있지 않습니다. 말씀이 최고의 권위입니다", "예화_적용":"교회의 결정도 전통이나 다수결이 아닌 성경 말씀에 기초해야 합니다"},
        {"대지":"3대지: 정의와 자비의 만남", "내용":"죄인을 처벌하되 무고한 자를 보호하는 것은 정의와 자비가 함께 작용하는 모습입니다. 이것이 하나님의 공의입니다", "예화_적용":"용서하되 정의를 포기하지 않고, 처벌하되 자비를 잃지 않는 것이 성경적 리더십입니다"},
        {"대지":"결론", "내용":"우리의 모든 판단과 결정이 하나님의 말씀에 근거하기를 원합니다. 감정이 아닌 말씀, 관습이 아닌 원칙에 따라 살아갑시다", "예화_적용":"이번 주 중요한 결정을 내릴 때 '성경은 이것에 대해 무엇이라 하는가?'를 먼저 물어봅시다"}
    ],
